DO $$ DECLARE id uuid; BEGIN SELECT r.legal_entity_id INTO STRICT id FROM establishment.group_identifier i JOIN establishment.group_identifier_type t USING(group_identifier_type_id) JOIN establishment.establishment_party_role r USING(establishment_party_role_id) WHERE t.name='Group UID' AND i.value='3839'; IF NOT EXISTS(SELECT 1 FROM establishment.legal_entity_address l JOIN establishment.address a USING(address_id) WHERE l.legal_entity_id=id AND l.address_purpose_id=3 AND l.is_current AND a.address_line_1='300 Victoria Avenue East Victoria Avenue East' AND a.address_line_2='Blackley' AND a.town='Manchester' AND a.postcode='M9 7SS') THEN RAISE EXCEPTION 'T16 address is missing'; END IF; END $$;
SELECT 'T16 group-address checks passed' AS result;
